mapper.select:
SELECT COALESCE(SUM(CAST(buy_amount AS REAL)), 0)
FROM trading_history_master
WHERE system_type = #{systemType}
  AND market_currency = #{marketCurrency}
  AND status = 'OPEN'
  AND sell_time IS NULL

SELECT COUNT(*)
FROM orders
WHERE requested_at >= #{from}
  AND requested_at < #{to}

SELECT COUNT(*)
FROM orders
WHERE idempotency_key = #{idempotencyKey}

mapper.update:
UPDATE pilot_positions
SET updated_at = #{updatedAt}
WHERE id = #{id}
  AND status = 'OPEN'

mapper.select:
SELECT id
FROM trading_history_master
WHERE system_type = #{systemType}
  AND symbol = #{symbol}
  AND buy_time = #{buyTime}
  AND status = 'OPEN'
ORDER BY id DESC
LIMIT 1

mapper.update:
UPDATE trading_history_master
SET sell_price = #{sellPrice},
    sell_time = #{sellTime},
    pnl_ratio = #{pnlRatio},
    force_liquidation_flag = #{forceLiquidationFlag},
    integrity_verified_at = #{sellTime},
    status = 'CLOSED',
    updated_at = #{sellTime}
WHERE id = #{masterId}
  AND system_type = #{systemType}
  AND symbol = #{symbol}
  AND status = 'OPEN'
  AND sell_price IS NULL

UPDATE pilot_positions
SET status = 'CLOSED',
    closed_at = #{closedAt},
    updated_at = #{closedAt}
WHERE symbol = #{symbol}
  AND status = 'OPEN'
